"id": "G03-005",
"chapter": 3,
"number": 5,
"stem": "Viewpoint ________ is the ability to recognize the same object even if it is seen from different perspectives.",
"options": [
"consistency",
"resistance",
"constancy",
"invariance"
],
"correct": 3,
